# Test reraise as decorator with callable into
import sys
sys.path.insert(0, '/root/repo')

from funcy.flow import reraise

@reraise(ValueError, lambda e: RuntimeError('wrapped: ' + str(e)))
def bad_func():
    raise ValueError("bad")

try:
    bad_func()
except Exception as e:
    print(f"Caught: {type(e).__name__}: '{e}'")
